{
  "bioavailability_prediction": "high",
  "confidence": "high",
  "revision_action": "keep",
  "supportive_card_ids": ["C21", "C51", "C37", "C32", "C54", "C57", "C59", "C65", "C64", "C73", "C74", "C76", "C77"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C21", "C51", "C37", "C32", "C54", "C59", "C65", "C64", "C76", "C77"],
  "claims": [
    {
      "claim": "The query is carbamazepine, a neutral lipophilic low-MW tricyclic urea; the closest gold-context analog thalidomide showed probably high absolute oral bioavailability (80–100%) at low doses in fasting volunteers, supporting F ≥ 20%.",
      "card_ids": ["C21"]
    },
    {
      "claim": "L4 direct intestinal absorption for the same dibenzazepine carboxamide scaffold: oxcarbazepine absorption was essentially complete after a single oral radiolabeled dose in healthy volunteers, supporting high intestinal absorption for carbamazepine.",
      "card_ids": ["C51"]
    },
    {
      "claim": "L3 oral exposure records show measurable systemic exposure after oral dosing of carbamazepine-scaffold drugs: carbamazepine-10,11-epoxide AUC12 was 9.98 µg·h/mL after oral carbamazepine 200 mg BID, and fed-state Cmax of the eslicarbazepine metabolite was 12.8 µg/mL after oral eslicarbazepine acetate, indicating oral absorption is not impaired in the fed state.",
      "card_ids": ["C37", "C32"]
    },
    {
      "claim": "L5 Caco-2 bidirectional records for neutral lipophilic aromatic amide/urea/heterocycle compounds show high passive permeability and low efflux ratios (ER ≈ 0.96–1.23), indicating no significant gut-wall efflux for this compound class; these are mechanistic, not direct carbamazepine F measurements.",
      "card_ids": ["C54", "C57", "C59", "C65", "C64"]
    },
    {
      "claim": "L6 hepatic/metabolic records do not provide affirmative evidence of F < 20% for carbamazepine: BPCPU was metabolically stable in rat hepatocytes/microsomes (C76/C77/C74/C73), while oxcarbazepine AKR intrinsic-clearance and MHD glucuronidation records (C66/C71/C75) concern a different molecule/metabolite and do not establish low carbamazepine F; C69 only shows cimetidine increased epoxide half-life by 10–20%.",
      "card_ids": ["C76", "C77", "C74", "C73", "C66", "C71", "C75", "C69"]
    },
    {
      "claim": "No affirmative threshold-relevant evidence supports F < 20%; low-dissolution record C46 is for an unrelated molecule (OIB) and is not used as evidence against carbamazepine.",
      "card_ids": ["C46"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C66", "C67", "C68", "C69", "C70", "C71", "C72", "C73", "C74", "C75", "C76", "C77"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for carbamazepine itself is supplied; C51 is oxcarbazepine absorption, not an F value.",
    "No fed-state-specific F for carbamazepine; C32 is fed but for eslicarbazepine acetate metabolite exposure.",
    "No direct carbamazepine Caco-2/efflux or intestinal metabolism record; L5 records are for other neutral lipophilic compounds.",
    "L6 hepatic clearance records are mostly for other molecules (BPCPU, oxcarbazepine, cyproheptadine) or metabolite half-life; no direct carbamazepine hepatic clearance or first-pass quantification.",
    "Several L5/L6 cards are duplicates or same-assay records and are not independent votes.",
    "Low-solubility/dissolution records are for unrelated molecules and are not transferable."
  ],
  "decision_summary": "Prediction high: carbamazepine is a neutral lipophilic low-MW tricyclic urea with favorable passive permeability; the closest analog thalidomide and same-scaffold oxcarbazepine absorption support F ≥ 20%. L6 hepatic/metabolic records are mixed and mostly non-carbamazepine, providing no affirmative evidence for F < 20%; fed-state-specific direct F and carbamazepine-specific first-pass quantification remain gaps."
}

